<div class="page-heading"><div><span class="eyebrow"><?= e(t('TURN RECORDS INTO PERSPECTIVE')) ?></span><h1><?= e(t('Reports & analysis')) ?></h1><p><?= e(t('Understand your cash flow across every business and your personal life.')) ?></p></div><a class="button" href="<?= e(page_link('export',['page'=>null])) ?>"><?= icon('download') ?><?= e(t('Export CSV')) ?></a></div>
<section class="panel filters-panel"><?php require BASE_PATH . '/app/Views/partials/filters.php'; ?></section>
<section class="metrics three-metrics"><?php foreach ([['Income',$report['totals']['income'],'success'],['Expenses',$report['totals']['expense'],'danger'],['Net income',$report['totals']['net'],'brand']] as [$label,$amount,$tone]): ?><div class="metric"><div><span class="metric-label"><?= e(t($label)) ?></span><strong><?= e(money($amount)) ?></strong><small><?= e($filters['from'] . ' → ' . $filters['to']) ?></small></div><span class="metric-icon <?= $tone ?>"><?= icon('reports') ?></span></div><?php endforeach ?></section>
<div class="report-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow"><?= e(t('FOLLOW THE FLOW')) ?></span><h2><?= e(t('Monthly cash flow')) ?></h2></div></div><?php require BASE_PATH . '/app/Views/partials/chart.php'; ?><div class="table-wrap"><table><thead><tr><th><?= e(t('Month')) ?></th><th class="number"><?= e(t('Income')) ?></th><th class="number"><?= e(t('Expenses')) ?></th><th class="number"><?= e(t('Net income')) ?></th></tr></thead><tbody><?php foreach ($report['months'] as $month): ?><tr><td><?= e($month['month']) ?></td><td class="number positive"><?= e(money($month['income'])) ?></td><td class="number negative"><?= e(money($month['expense'])) ?></td><td class="number amount"><?= e(money(\App\Services\Money::subtract($month['income'], $month['expense']))) ?></td></tr><?php endforeach ?><?php if (!$report['months']): ?><tr><td colspan="4" class="muted"><?= e(t('No records in this period.')) ?></td></tr><?php endif ?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow"><?= e(t('WHERE IT GOES')) ?></span><h2><?= e(t('Category breakdown')) ?></h2></div></div><?php $categoryMax=max([1,...array_column($report['categories'],'amount')]); foreach ($report['categories'] as $category): ?><div class="category-row"><div><strong><?= e($category['name']) ?></strong><?= status_badge($category['kind']) ?><span class="number"><?= e(money($category['amount'])) ?></span></div><div class="progress-track"><span class="<?= $category['kind']==='income' ? 'income-fill' : 'expense-fill' ?>" style="width:<?= round((float) $category['amount']/$categoryMax*100,2) ?>%"></span></div></div><?php endforeach ?><?php if (!$report['categories']): ?><div class="empty-state"><?= icon('categories') ?><strong><?= e(t('No category activity yet')) ?></strong><span><?= e(t('Categorized records will appear here.')) ?></span></div><?php endif ?></section></div>
<section class="panel ledger-panel"><div class="panel-heading"><div><span class="eyebrow"><?= e(t('SIDE BY SIDE')) ?></span><h2><?= e(t('Business & personal comparison')) ?></h2></div></div><div class="table-wrap"><table><thead><tr><th><?= e(t('Business / personal')) ?></th><th><?= e(t('Type')) ?></th><th class="number"><?= e(t('Income')) ?></th><th class="number"><?= e(t('Expenses')) ?></th><th class="number"><?= e(t('Net income')) ?></th><th class="number"><?= e(t('Net / income')) ?></th></tr></thead><tbody><?php foreach ($report['businesses'] as $business): ?><tr><td><strong><?= e($business['name']) ?></strong></td><td><?= e(t(ucfirst($business['kind']))) ?></td><td class="number positive"><?= e(money($business['income'])) ?></td><td class="number negative"><?= e(money($business['expense'])) ?></td><td class="number amount"><?= e(money(\App\Services\Money::subtract($business['income'], $business['expense']))) ?></td><td class="number"><?= (float) $business['income'] ? number_format((\App\Services\Money::subtract($business['income'], $business['expense']))/(float) $business['income']*100,1) . '%' : '—' ?></td></tr><?php endforeach ?><?php if (!$report['businesses']): ?><tr><td colspan="6"><div class="empty-state"><strong><?= e(t('No records in this period.')) ?></strong></div></td></tr><?php endif ?></tbody></table></div></section>
<p class="quiet-note"><?= icon('reports') ?><?= e(t('Cash basis: only received income and paid expenses are included. Unpaid balances, opening balances, and transfers do not count as income or expenses.')) ?></p>
